export function sanitizeJSON(jsonString: string): string {
  try {
    let result = jsonString.trim();
    const chars: string[] = [];
    let inString = false;
    let escapeNext = false;

    for (let i = 0; i < result.length; i++) {
      const char = result[i];

      if (escapeNext) {
        chars.push(char);
        escapeNext = false;
        continue;
      }

      if (char === '\\') {
        chars.push(char);
        escapeNext = true;
        continue;
      }

      if (char === '"' && (i === 0 || result[i - 1] !== '\\')) {
        inString = !inString;
        chars.push(char);
        continue;
      }

      if (inString && (char === '\n' || char === '\r')) {
        chars.push(' ');
        continue;
      }

      chars.push(char);
    }

    result = chars.join('');
    result = result.replace(/,\s*}/g, '}');
    result = result.replace(/,\s*]/g, ']');

    result = result.replace(/"([^"]*?)(['"])([^"]*?)"/g, (match, _prefix

